INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','flashcard','What is the classic immunofluorescence pattern in post-streptococcal glomerulonephritis?','["Granular (''starry sky'' or ''lumpy-bumpy'') IgG and C3 deposits along capillary walls and in the mesangium — due to circulating immune complex deposition"]','A','Post-streptococcal GN results from deposition of immune complexes containing streptococcal antigens. The granular IF pattern contrasts with the linear pattern of anti-GBM disease. Electron microscopy shows subepithelial ''hump-shaped'' deposits.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','flashcard','What is IgA nephropathy (Berger disease) and how does it present clinically?','["The most common primary glomerulonephritis worldwide; mesangial IgA deposits; presents with recurrent macroscopic haematuria coinciding with upper respiratory tract infections (''synpharyngitic haematuria'')"]','A','Unlike post-streptococcal GN (haematuria 1-3 weeks after infection), IgA nephropathy haematuria is simultaneous with the infection. Serum IgA is elevated in 50%. Prognosis is variable — ~20-30% progress to ESRD over 20 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','flashcard','Name the three types of rapidly progressive (crescentic) glomerulonephritis (RPGN) and their distinguishing features','["Type I: Anti-GBM disease (Goodpasture) — linear IgG on IF. Type II: Immune complex (SLE, post-infectious) — granular IF. Type III: Pauci-immune (ANCA-associated — GPA, MPA) — negative IF, ANCA positive"]','A','All three types show crescents on light microscopy and rapid GFR decline. Type I: anti-GBM antibodies target alpha-3 collagen IV; lung involvement causes Goodpasture syndrome. Type III is most common in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','flashcard','What are crescents in glomerulonephritis? Where do they form and what cells compose them?','["Crescents are accumulations of cells in the urinary space (Bowman space) compressing the glomerular tuft. Composed of proliferating parietal epithelial cells of Bowman capsule + infiltrating monocytes/macrophages. Form in response to fibrin leakage into Bowman space"]','A','Fibrin leakage through disrupted GBM triggers parietal epithelial cell proliferation and monocyte recruitment. Fibronectin and other matrix proteins organise around the proliferating cells. Crescents indicate severe glomerular injury with high risk of progression to ESRD if untreated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','flashcard','What is the electron microscopic hallmark of post-streptococcal glomerulonephritis?','["Subepithelial ''hump-shaped'' electron-dense immune complex deposits on the outer (epithelial) side of the GBM"]','A','These subepithelial humps correspond to the ''starry sky'' granular IF pattern. They are the pathognomonic EM finding of post-streptococcal GN and may also be seen in other post-infectious GN. They are on the opposite side of the GBM compared to membranous nephropathy deposits.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','flashcard','What is the pathogenesis of Goodpasture syndrome and which organs are targeted?','["Autoantibodies against the alpha-3 chain of type IV collagen (in the non-collagenous NC1 domain of the GBM and alveolar basement membrane) → immune-mediated destruction of GBM and ABM → RPGN + pulmonary haemorrhage"]','A','Goodpasture syndrome is a Type II hypersensitivity reaction. The target antigen (alpha-3 chain of type IV collagen) is found in GBM and pulmonary ABM. Diagnosis: anti-GBM antibodies in serum + linear IgG on kidney IF. Treatment: plasmapheresis + steroids + cyclophosphamide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','hard','flashcard','Alport syndrome: gene mutated, inheritance, clinical triad, and EM finding','["COL4A5 mutation (X-linked, ~80%); COL4A3 or COL4A4 mutations (autosomal). Clinical triad: haematuria + progressive renal failure + sensorineural hearing loss (+/- ocular abnormalities). EM: irregular thinning, thickening, and lamellation (''basket-weave'') of GBM"]','A','Alport syndrome is a hereditary nephritis from type IV collagen chain mutations. X-linked form (COL4A5) is more severe in males. No specific treatment; ACE inhibitors may slow progression. Renal transplant can trigger anti-GBM nephritis (transplanted kidney has normal collagen).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','flashcard','What serum complement levels are expected in post-streptococcal GN vs. IgA nephropathy?','["Post-streptococcal GN: low C3 (and sometimes C4) — complement is consumed by immune complex deposition. IgA nephropathy: normal complement levels — IgA activates complement via alternative pathway only locally, serum levels remain normal"]','A','Serum complement helps differentiate GN subtypes: Low C3+C4 = lupus nephritis, post-infectious, MPGN type I. Low C3, normal C4 = post-streptococcal (alternative pathway), MPGN type II, atypical HUS. Normal complement = IgA nephropathy, Goodpasture, pauci-immune RPGN, FSGS, MCD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','flashcard','What does the ANCA test detect and which GN types are ANCA-associated?','["ANCA (anti-neutrophil cytoplasmic antibody): c-ANCA (anti-PR3) in granulomatosis with polyangiitis (GPA/Wegener''''s); p-ANCA (anti-MPO) in microscopic polyangiitis (MPA) and eosinophilic GPA (EGPA). Both cause pauci-immune (Type III) RPGN"]','A','ANCA-associated vasculitides cause the most common pauci-immune RPGN in adults. Pauci-immune means little/no immune complex deposits on IF. ANCA activates neutrophils at vessel walls, causing small vessel vasculitis and necrotising glomerulonephritis. Renal biopsy: crescents + fibrinoid necrosis + negative IF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','hard','flashcard','What is the ''nephritic-nephrotic overlap'' and which GN diseases can present with both syndromes?','["Some GN diseases cause enough proteinuria to fulfil nephrotic criteria PLUS haematuria/red cell casts/hypertension (nephritic features): MPGN (membranoproliferative GN), lupus nephritis (Class III/IV), and sometimes IgA nephropathy with heavy proteinuria"]','A','MPGN (mesangiocapillary GN) classically causes both nephritic and nephrotic features. The ''tram-track'' or ''double contour'' GBM on silver stain results from mesangial interposition and new GBM synthesis. Type I MPGN is immune complex-mediated; Type II (dense deposit disease) involves C3 nephritic factor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','flashcard','What are the four defining features of nephrotic syndrome?','["1. Massive proteinuria >3.5 g/day (>3.5 g/1.73m2/day); 2. Hypoalbuminaemia <3 g/dL; 3. Generalised oedema (anasarca); 4. Hyperlipidaemia and lipiduria (oval fat bodies, fatty casts)"]','A','Mechanism: proteinuria → hypoalbuminaemia → reduced plasma oncotic pressure → oedema. Liver increases lipoprotein synthesis to compensate for reduced oncotic pressure → hyperlipidaemia. Lipiduria: lipoproteins filtered through damaged GBM appear as oval fat bodies in urine (Maltese cross under polarised light).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','flashcard','Minimal change disease: light microscopy, EM, IF, response to steroids, and common association in adults','["LM: normal glomeruli. EM: diffuse effacement (fusion) of podocyte foot processes — the only abnormality. IF: negative (no immune deposits). Steroid response: excellent in children (>90%). Adult association: Hodgkin lymphoma"]','A','MCD is the most common cause of nephrotic syndrome in children (peak 2-6 years). The pathogenesis involves T-cell dysfunction producing a permeability factor that injures podocytes. The absence of immune deposits and good steroid response are key features. Relapse is common (>50%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','flashcard','What is the characteristic light microscopy appearance of membranous nephropathy and what causes the ''spikes''?','["LM (silver stain): diffuse thickening of GBM with ''spike and dome'' appearance — subepithelial immune complex deposits (''domes'') with GBM material laid down between them forming ''spikes''. IF: granular IgG (predominantly IgG4) and C3 along GBM"]','A','In membranous nephropathy, anti-PLA2R (or THSD7A) IgG4 antibodies bind to podocyte antigens, forming subepithelial deposits. The GBM reacts by laying down new basement membrane material between deposits → spikes on silver stain. Eventually deposits are incorporated into GBM → thick irregular GBM. Stages I-IV by severity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','flashcard','Focal segmental glomerulosclerosis (FSGS): definition, secondary causes, and prognosis','["Focal (affects some glomeruli) and segmental (affects part of each glomerulus) sclerosis/hyalinosis. Secondary causes: HIV (collapsing variant), heroin use, sickle cell disease, morbid obesity, reduced renal mass. Poor prognosis: ~50% reach ESRD in 10 years if steroid-resistant"]','A','FSGS may be primary (idiopathic, circulating permeability factor) or secondary (adaptive, genetic). LM shows sclerosis and hyalinosis in segments of some glomeruli — must sample multiple glomeruli to detect. IF: IgM and C3 in sclerotic segments (non-specific trapping). EM: foot process effacement. Collapsing FSGS (HIV-associated) has worst prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','flashcard','Diabetic nephropathy: what are the earliest and late histological changes?','["Earliest: GBM thickening + mesangial expansion (detectable 1-2 years after onset). Late: nodular glomerulosclerosis (Kimmelstiel-Wilson nodules) + diffuse glomerulosclerosis + arteriolar hyalinosis (afferent AND efferent — efferent hyalinosis is virtually pathognomonic of diabetes)"]','A','Diabetic nephropathy progresses through 5 stages (Mogensen). Microalbuminuria (30-300 mg/day) is the earliest clinical marker. Proteinuria then GFR decline follow. Kimmelstiel-Wilson nodules are laminated matrices of collagen in mesangium. Efferent arteriolar hyalinosis is nearly specific for diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','hard','flashcard','What is the PLA2R antibody and its significance in membranous nephropathy?','["Anti-phospholipase A2 receptor (PLA2R) antibody is the primary pathogenic autoantibody in ~70% of idiopathic (primary) membranous nephropathy. PLA2R is expressed on podocytes. Serum PLA2R titre correlates with disease activity and can monitor response to treatment (rituximab, cyclophosphamide)"]','A','Discovery of anti-PLA2R transformed understanding of primary membranous nephropathy from ''idiopathic'' to autoimmune. Anti-PLA2R is predominantly IgG4 (non-complement-fixing in isolation but activates lectin pathway). Secondary MN (lupus, malignancy, hepatitis B) is PLA2R-negative. Anti-THSD7A antibody is found in ~3-5% of PLA2R-negative primary MN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','flashcard','What is the significance of nephrotic syndrome in terms of thrombotic complications?','["Nephrotic syndrome causes a hypercoagulable state due to urinary loss of anticoagulant proteins (antithrombin III, protein C, protein S) and increased synthesis of procoagulant factors. Risk of renal vein thrombosis (especially in membranous nephropathy ~35%), DVT, and pulmonary embolism"]','A','Membranous nephropathy has the highest thrombotic risk among nephrotic diseases. Patients may present with acute flank pain, haematuria, and worsening renal function from renal vein thrombosis. Prophylactic anticoagulation is considered in severe nephrotic syndrome (albumin <2.5 g/dL), especially with membranous nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','flashcard','What are oval fat bodies in urine and how are they identified?','["Oval fat bodies are tubular epithelial cells or free fat droplets containing reabsorbed lipoproteins filtered through the damaged glomerulus in nephrotic syndrome. Identified by: Maltese cross (birefringent) pattern under polarised light microscopy (lipid droplets have characteristic appearance)"]','A','Oval fat bodies form when proximal tubular epithelial cells reabsorb the excessive lipoproteins filtered through the damaged GBM in nephrotic syndrome. Under polarised light, cholesterol esters show a characteristic Maltese cross (birefringent pattern). Their presence in urine sediment strongly suggests nephrotic syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','flashcard','Why do nephrotic patients develop hyperlipidaemia?','["Hypoalbuminaemia reduces plasma oncotic pressure → liver responds by increasing lipoprotein synthesis (VLDL, LDL) to try to raise oncotic pressure. Also, reduced lipoprotein lipase activity decreases peripheral lipid clearance → net hyperlipidaemia"]','A','The compensatory increase in hepatic lipoprotein synthesis is non-selective — while albumin synthesis does increase, the liver also synthesises more VLDL and LDL. Reduced lipoprotein lipase (LPL) activity (possibly due to loss of LPL cofactors in urine) further reduces lipid clearance. Long-standing nephrotic hyperlipidaemia accelerates atherosclerosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','hard','flashcard','Name three causes of secondary membranous nephropathy (PLA2R-negative)','["Systemic lupus erythematosus (lupus membranous — Class V), hepatitis B infection, malignancy (solid tumours — lung, colon, breast — in older patients), drugs (gold, penicillamine, NSAIDs), and hepatitis C (less commonly)"]','A','Secondary membranous nephropathy should always be excluded before diagnosing primary (idiopathic) MN. In patients over 60 with new-onset MN, malignancy screen is essential (CT chest/abdomen/pelvis). Hepatitis B surface antigen deposits can be detected in the GBM. Lupus MN (Class V) shows full-house IF (IgG, IgA, IgM, C3, C1q) unlike primary MN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','flashcard','What are the three categories of acute kidney injury (AKI) with examples of each?','["1. Pre-renal: reduced renal perfusion (haemorrhage, dehydration, cardiac failure, sepsis); 2. Intrinsic (intra-renal): ATN (ischaemic/toxic), GN, interstitial nephritis, vascular; 3. Post-renal: obstruction (stones, BPH, pelvic tumour, bilateral ureteric obstruction)"]','A','Pre-renal AKI: FENa <1%, urine concentrated. ATN: FENa >2%, muddy brown casts. Post-renal: hydronephrosis on US, relief of obstruction restores function. The most common cause of AKI in hospitalised patients is pre-renal (often evolving to ATN if untreated).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','flashcard','What urinary finding is pathognomonic of acute tubular necrosis (ATN)?','["Muddy brown (''granular'') casts — composed of sloughed tubular epithelial cells and cellular debris embedded in Tamm-Horsfall protein. Also: renal tubular epithelial cell casts"]','A','Muddy brown granular casts form when necrotic tubular epithelial cells shed into the tubular lumen and aggregate with Tamm-Horsfall protein. Their presence in urine sediment is the hallmark of ATN. FENa >2% in ATN (tubular reabsorption impaired) distinguishes it from pre-renal AKI (FENa <1%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','flashcard','What are the three phases of ischaemic ATN and their characteristics?','["1. Initiation phase (~36 hours): inciting ischaemic event, slight oliguria, BUN rising. 2. Maintenance/oliguric phase (10-14 days): sustained oliguria (40-400 mL/day), rising BUN/Cr, electrolyte disturbances. 3. Recovery/diuretic phase: gradual increase in urine output (may have massive polyuria from tubular dysfunction), gradual return of GFR"]','A','The maintenance phase is dominated by metabolic complications: hyperkalaemia (can cause fatal arrhythmias), metabolic acidosis, hyperphosphataemia, fluid overload. Death in ATN is most often from complications during this phase. Recovery phase can take weeks to months; tubular regeneration occurs from surviving cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','flashcard','Which nephron segments are most vulnerable to ischaemic vs. toxic ATN?','["Ischaemic ATN: proximal convoluted tubule (S3 segment / pars recta) and medullary thick ascending limb of Henle — highest metabolic demand, poor oxygen supply in outer medulla. Toxic ATN (aminoglycosides, cisplatin): proximal convoluted tubule S1 and S2 segments (most drug accumulation/active transport)"]','A','The outer medulla is the most hypoxic zone of the kidney (even under normal conditions) due to countercurrent exchange. Ischaemia disproportionately affects the straight proximal tubule (S3) in the outer medulla. Aminoglycosides accumulate in proximal tubule cells via megalin-mediated endocytosis and cause lysosomal damage and apoptosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','flashcard','FENa (fractional excretion of sodium) formula and interpretation in AKI','["FENa = (urine Na / serum Na) / (urine Cr / serum Cr) × 100%. FENa <1% = pre-renal AKI (intact tubular Na reabsorption). FENa >2% = intrinsic AKI/ATN (tubular reabsorption impaired). Exception: FENa may be <1% in contrast nephropathy, myoglobinuria, early obstruction, and GN"]','A','FENa is the most reliable index to distinguish pre-renal from intrinsic AKI. FEUrea (<35%) is preferred when diuretics have been given (diuretics increase urine Na even in pre-renal states). Remember: FENa <1% only means tubules are working — this occurs in pre-renal AND some intrinsic causes (contrast, GN, early obstruction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','flashcard','Rhabdomyolysis causes ATN through which mechanisms and how is it treated?','["Rhabdomyolysis (muscle breakdown) releases myoglobin → myoglobin causes ATN by: (1) haem protein direct cytotoxicity to tubular cells; (2) tubular obstruction by myoglobin casts; (3) free radical (ROS) generation. Marked by: dark ''cola-coloured'' urine, dipstick positive for haem but no RBCs on microscopy, elevated CK (>5000 IU/L). Treatment: aggressive IV fluid resuscitation (saline), urinary alkalinisation (sodium bicarbonate), treat underlying cause"]','A','Volume depletion and acidic urine potentiate myoglobin precipitation in tubules. Classic causes: trauma, prolonged immobilisation (''crush syndrome''), seizures, extreme exercise, statins, alcohol, infections. Hyperkalaemia and hyperphosphataemia from muscle necrosis can be life-threatening. Early aggressive fluid resuscitation (3-6 L/day) is the cornerstone of treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','hard','flashcard','What is the KDIGO (2012) staging criteria for AKI?','["Stage 1: Cr ×1.5-1.9 baseline OR rise ≥0.3 mg/dL in 48h OR UO <0.5 mL/kg/h for 6-12h. Stage 2: Cr ×2.0-2.9 baseline OR UO <0.5 mL/kg/h for ≥12h. Stage 3: Cr ×3.0 baseline OR ≥4.0 mg/dL OR initiation of RRT OR UO <0.3 mL/kg/h for ≥24h or anuria ≥12h"]','A','KDIGO AKI criteria require baseline creatinine or urine output context. AKI is defined as: rise in serum creatinine ≥0.3 mg/dL within 48h, OR rise ≥1.5× baseline within 7 days, OR urine output <0.5 mL/kg/h for ≥6h. Early AKI recognition and management is critical for outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','flashcard','Contrast-induced AKI: risk factors and prevention strategies','["Risk factors: pre-existing CKD (most important), diabetes, volume depletion, heart failure, large contrast volumes, NSAIDs. Prevention: IV hydration with 0.9% saline before/after, use minimum contrast dose, use iso-osmolar/low-osmolar contrast, hold nephrotoxic drugs (NSAIDs, metformin). N-acetylcysteine controversial (not proven)"]','A','Contrast-induced AKI typically peaks at 3-5 days and recovers by 7-10 days. Mechanism: direct renal tubular toxicity + renal medullary vasoconstriction (via adenosine and endothelin). Prevent by identifying at-risk patients and pre-hydrating. CO2 angiography can be used in high-risk patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','flashcard','What is hepatorenal syndrome (HRS) and how does it relate to AKI classification?','["HRS is a form of pre-renal AKI in patients with advanced liver disease (cirrhosis, acute liver failure) characterised by marked splanchnic vasodilation, reduced effective arterial blood volume, and intense renal vasoconstriction. Functional renal failure with no structural damage. Type 1 HRS: rapid progression (Cr doubles in <2 weeks). Type 2 HRS: slower course associated with refractory ascites"]','A','HRS is a functional AKI — kidneys are structurally normal (if transplanted into a healthy recipient they function normally). Pathogenesis: portal hypertension → splanchnic vasodilation → reduced effective blood volume → RAAS and SNS activation → intense renal vasoconstriction. Treatment: terlipressin (vasopressin analogue) + albumin; liver transplant is definitive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','hard','flashcard','What is the distinction between acute kidney injury (AKI) and acute-on-chronic kidney disease (AoCKD)?','["AKI = sudden reduction in kidney function in patients with previously normal kidneys. AoCKD = acute deterioration in patients with pre-existing CKD (GFR already reduced). AoCKD has higher risk of non-recovery and progression to ESRD than AKI in isolation. Baseline creatinine >1.5 mg/dL suggests underlying CKD"]','A','Distinguishing AKI from AoCKD has prognostic implications. AKI is potentially fully reversible if cause is removed. AoCKD: acute component may recover but baseline CKD remains. Kidney size on US: small kidneys suggest CKD (shrunken, fibrotic); normal/large kidneys = AKI or early CKD. Anaemia + hypocalcaemia + hyperphosphataemia suggest pre-existing CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','flashcard','What is the KDIGO definition of chronic kidney disease (CKD)?','["Kidney damage or GFR <60 mL/min/1.73m2 for >3 months, with health implications. Damage markers include: albuminuria (ACR ≥30 mg/g), urine sediment abnormalities, electrolyte disorders from tubular dysfunction, structural abnormalities on imaging, history of kidney transplant"]','A','The 3-month duration criterion distinguishes CKD from AKI. CKD is classified by GFR (G1-G5) and albuminuria (A1-A3). GFR and albuminuria together determine risk of progression. Both can be present independently to define CKD. Staging guides management and referral thresholds.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','flashcard','Name the two most common causes of CKD/ESRD in developed countries','["1. Diabetic nephropathy (~40-44% of ESRD) — most common single cause. 2. Hypertensive nephrosclerosis (~25-30%). Together account for ~70% of ESRD requiring dialysis"]','A','Diabetic nephropathy affects both type 1 and type 2 DM. Onset: microalbuminuria → overt proteinuria → declining GFR. Hypertensive nephrosclerosis: benign (hyaline arteriolosclerosis, slow progression) and malignant (accelerated vascular damage). Other causes: GN (10%), polycystic kidney disease (5%), pyelonephritis/reflux nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','flashcard','What is the final common histological pathway of CKD regardless of initial cause?','["Interstitial fibrosis and tubular atrophy (IFTA) — reflects irreversible nephron loss. Also: glomerulosclerosis (global), vascular sclerosis. Grossly: bilaterally shrunken, granular, fibrotic kidneys"]','A','IFTA on renal biopsy is the best histological predictor of long-term renal prognosis. It reflects replacement of functioning nephron units with fibrotic tissue. Remaining nephrons undergo hypertrophy and hyperfiltration (intact nephron hypothesis) to compensate, but this ultimately accelerates further scarring. IFTA score correlates inversely with residual GFR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','flashcard','What metabolic complications develop in CKD stage 3-5?','["1. High anion gap metabolic acidosis (failure to excrete H+). 2. Hyperkalaemia (reduced tubular secretion). 3. Hyperphosphataemia (reduced phosphate excretion). 4. Hypocalcaemia (reduced calcitriol synthesis). 5. Secondary hyperparathyroidism → renal osteodystrophy. 6. Normochromic normocytic anaemia (reduced EPO). 7. Hypertension"]','A','These complications are interrelated: reduced 1-alpha-hydroxylase → low calcitriol → low Ca2+ → PTH rises (secondary hyperparathyroidism) → bone resorption (osteitis fibrosa cystica). Hyperphosphataemia also directly stimulates PTH and causes soft tissue/vascular calcification. Management: phosphate binders, activated vitamin D analogues (calcitriol), cinacalcet, ESAs for anaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','flashcard','What are the indications for initiating renal replacement therapy (RRT) in CKD stage 5?','["Absolute indications (AEIOU): Acidosis refractory to treatment, Electrolyte disturbances (refractory hyperkalaemia), Intoxication (drug/toxin overdose), Overload (refractory pulmonary oedema), Uraemic symptoms (encephalopathy, pericarditis, neuropathy, bleeding). GFR usually <10-15 mL/min in symptomatic CKD"]','A','RRT options: haemodialysis (HD), peritoneal dialysis (PD), or kidney transplantation. Transplantation is the preferred option as it provides superior outcomes. HD requires arteriovenous access (AV fistula, graft, or catheter). PD uses the peritoneal membrane as a dialysis membrane — suitable for home dialysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','hard','flashcard','Explain why ACE inhibitors and ARBs are renoprotective in CKD with proteinuria','["ACE inhibitors/ARBs block angiotensin II → dilate efferent arteriole preferentially → reduce intraglomerular pressure → reduce glomerular hyperfiltration and proteinuria → slow nephron loss. Also reduce proteinuria-mediated tubulointerstitial injury (proteinuria is directly nephrotoxic to tubular cells)"]','A','The Brenner hypothesis: glomerular hypertension from hyperfiltration in remaining nephrons drives FSGS in those nephrons, accelerating progression. ACE inhibitors/ARBs reduce this pressure. Evidence: RENAAL, IDNT, HOPE trials. Monitor for hyperkalaemia and 30% rise in creatinine (acceptable — reflects reduced efferent constriction). Contraindicated in bilateral RAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','flashcard','What is uraemic encephalopathy and when does it typically occur?','["Uraemic encephalopathy is a neurological syndrome from accumulation of uraemic toxins (urea, guanidine compounds, indoles, phenols) in advanced CKD (GFR <10-15 mL/min). Features: lethargy, confusion, asterixis (''uraemic flap''), seizures, coma. Uraemic frost (rare): urea crystallises on skin"]','A','Uraemic toxins accumulate because the kidneys cannot excrete the daily metabolic acid/waste load. Urea itself is relatively non-toxic but is a marker of other toxic substances. Asterixis (liver flap, metabolic tremor) is non-specific — also seen in hepatic encephalopathy, CO2 narcosis. Dialysis rapidly reverses uraemic encephalopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','flashcard','Why are CKD patients at increased risk of cardiovascular disease?','["CKD is an independent cardiovascular risk factor. Contributing factors: hypertension, dyslipidaemia, anaemia (cardiac hypertrophy), uraemic endothelial dysfunction, vascular calcification (from hyperphosphataemia and hyperparathyroidism), chronic inflammation, and volume overload. CVD causes >50% of deaths in CKD/ESRD"]','A','The ''cardiorenal syndrome'' reflects bidirectional heart-kidney interaction. CKD patients have markedly elevated CV risk even at early stages. Vascular calcification in CKD is mediated by high phosphate and FGF23 levels driving vascular smooth muscle cells to calcify. Cardiovascular risk management (statins, BP control, glycaemic control) is essential in CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','flashcard','What is the role of FGF23 in CKD-mineral bone disorder?','["FGF23 (fibroblast growth factor 23) is produced by osteocytes in response to hyperphosphataemia. It acts on the kidney to: (1) increase phosphate excretion (phosphaturic effect) and (2) inhibit 1-alpha-hydroxylase (reducing calcitriol synthesis). In early CKD, elevated FGF23 maintains phosphate balance but at the cost of reduced calcitriol → secondary hyperparathyroidism"]','A','FGF23 rises early in CKD (even when phosphate is still normal) and is now recognised as an early biomarker of CKD-MBD. Massively elevated FGF23 levels in advanced CKD have been independently linked to left ventricular hypertrophy, cardiovascular mortality, and faster CKD progression. Klotho (FGF23 co-receptor) is reduced in CKD, further impairing FGF23 signalling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','hard','flashcard','Describe the histological stages of diabetic nephropathy on renal biopsy','["Stage I: GBM thickening + mesangial expansion (earliest EM changes). Stage II: more marked mesangial expansion, still <25% of mesangium. Stage III (incipient): nodular glomerulosclerosis (Kimmelstiel-Wilson nodules). Stage IV: advanced diffuse + nodular sclerosis with >50% glomeruli affected. Arteriolar hyalinosis (especially efferent arteriole) + tubular atrophy + interstitial fibrosis also present"]','A','Kimmelstiel-Wilson nodules (nodular glomerulosclerosis) are laminated matrix deposits in the periphery of the mesangium, staining PAS+ and silver-negative. Efferent arteriolar hyalinosis is virtually pathognomonic of diabetic nephropathy. Capsular drop (eosinophilic material between parietal cells and Bowman capsule) and fibrin cap lesions are other specific features.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','easy','flashcard','What is the classic clinical triad of acute drug-induced interstitial nephritis (AIN)?','["Fever + skin rash + eosinophilia — appearing 2-40 weeks after starting the culprit drug. Renal biopsy: interstitial oedema with lymphocyte, plasma cell, and eosinophil infiltrate. Eosinophiluria on Hansel stain (insensitive but specific). Urine: white cells, white cell casts, mild proteinuria"]','A','Common causative drugs: penicillins (esp. methicillin), NSAIDs, PPIs, sulphonamides, rifampicin, cephalosporins, allopurinol, ciprofloxacin. NSAIDs-induced AIN may present with nephrotic syndrome (minimal change pattern) + AIN simultaneously. Treatment: remove offending drug; short course of corticosteroids if no improvement in 1-2 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','flashcard','What is Fanconi syndrome? List the urinary losses and causes','["Generalised proximal tubular dysfunction causing wasting of: glucose (normoglycaemic glycosuria), amino acids, phosphate, urate, bicarbonate (type 2 RTA), potassium, sodium, and low-molecular-weight proteins. Results in hypophosphataemia, hypokalaemia, metabolic acidosis, and growth failure in children"]','A','Causes of Fanconi syndrome: Wilson disease, galactosaemia, hereditary fructose intolerance (genetic metabolic diseases), multiple myeloma (light chains toxic to tubules), tenofovir (antiretroviral), lead/mercury/cadmium poisoning, outdated tetracyclines, ifosfamide. Cystinosis (lysosomal storage disease) is the most common genetic cause in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','flashcard','Describe the gross pathology of reflux nephropathy (chronic atrophic pyelonephritis)','["Coarse, irregular, asymmetric cortical scars — most prominent at upper and lower poles (where compound papillae allow intrarenal reflux). Scars overlie dilated and blunted calyces (calyceal clubbing). Affected kidney is small and shrunken. Contralateral kidney may be hypertrophied"]','A','Vesicoureteral reflux allows infected urine to reflux into collecting ducts via compound papillae at the poles, causing recurrent intrarenal infection and scarring. Voiding cystourethrogram (VCUG) confirms VUR. DMSA renal scan detects cortical scars. Reflux nephropathy is a leading cause of childhood hypertension and accounts for ~10-15% of ESRD in young adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','flashcard','What is the pathological mechanism of light chain cast nephropathy in multiple myeloma?','["Monoclonal free light chains (Bence Jones proteins) are filtered at the glomerulus and enter the tubular lumen. In the distal tubule, they bind to Tamm-Horsfall protein (uromodulin) — forming obstructive, dense, eosinophilic ''myeloma casts'' with a fractured appearance and surrounding giant cell reaction. Tubular obstruction + tubular cell toxicity → interstitial fibrosis → renal failure"]','A','Light chain casts are PAS-positive and have a characteristic fractured (crystalline) appearance with a syncytial giant cell reaction around them. Not all light chains are equally nephrotoxic — kappa chains are more likely to form casts than lambda chains. Coexisting causes of myeloma kidney include hypercalcaemia (ATN/nephrocalcinosis), amyloidosis (AL amyloid, nephrotic syndrome), and light chain deposition disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','easy','flashcard','What is the pathognomonic finding in acute pyelonephritis on urine microscopy?','["White cell (leucocyte) casts — neutrophils aggregated within tubular lumens, embedded in Tamm-Horsfall protein. Confirm infection is in the kidney (upper UTI). Also: bacteriuria, pyuria, possible haematuria"]','A','White cell casts are formed when neutrophils accumulate in renal tubular lumens (in response to infection) and are incorporated into the Tamm-Horsfall protein matrix. They are pathognomonic of upper UTI (pyelonephritis) — lower UTIs have WBCs in urine but these do not form casts. May also be seen in severe acute interstitial nephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','flashcard','Analgesic nephropathy (from long-term NSAID/phenacetin use): characteristic lesion and imaging findings','["Renal papillary necrosis — ischaemic necrosis of the renal papilla from accumulation of toxic NSAID metabolites in the medulla + direct PG inhibition causing medullary ischaemia. Sloughed papillae appear as filling defects in the calyx on IVP (''ring sign'') or CT. May cause haematuria, renal colic, or asymptomatic haematuria"]','A','Analgesic nephropathy was classically associated with phenacetin (now withdrawn) and mixed analgesic (aspirin + phenacetin + caffeine). NSAIDs alone can cause it with long-term heavy use. Also associated with sickling (sickle cell papillary necrosis), diabetes, obstruction, and severe acute pyelonephritis. Diagnosis: CT KUB without contrast showing shrunken calcified papillae with ring shadow.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','flashcard','What is the pathological basis of type 1 and type 2 renal tubular acidosis (RTA)?','["Type 1 (distal RTA): defective H+ secretion in the distal tubule/collecting duct → inability to acidify urine (pH always >5.5), hypokalaemia, nephrocalcinosis/nephrolithiasis. Type 2 (proximal RTA): defective HCO3- reabsorption in proximal tubule → bicarbonaturia, hypokalaemia. Causes type 2 as part of Fanconi syndrome"]','A','Type 1 RTA causes: Sjogren syndrome, primary biliary cholangitis, medullary sponge kidney, amphotericin B, lithium. Urine pH >5.5 even with systemic acidosis is diagnostic. Nephrocalcinosis from alkaline urine promotes calcium phosphate precipitation. Type 4 RTA (most common in CKD): hyperkalaemia + hyperchloraemic acidosis from hyporeninaemic hypoaldosteronism (diabetic nephropathy, NSAIDs).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','flashcard','How does lead nephropathy cause renal damage?','["Lead accumulates in proximal tubular cells → causes inclusion bodies (lead-protein complexes in nuclei), mitochondrial damage, and Fanconi syndrome acutely. Chronically: interstitial nephritis, IFTA, and slowly progressive CKD. Associated with gout (saturnine gout — lead inhibits urate excretion causing hyperuricaemia)"]','A','Lead nephropathy is an occupational/environmental hazard (paint, petrol, batteries). Acute lead poisoning: abdominal pain, encephalopathy, peripheral neuropathy. Renal: lead-induced inclusion bodies in proximal tubular nuclei (acid-fast, PAS-negative) are pathognomonic. Diagnosis: whole blood lead level, 24h urine lead after EDTA chelation challenge. Treatment: chelation with DMSA or EDTA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','easy','flashcard','What is xanthogranulomatous pyelonephritis (XGP) and what organisms cause it?','["XGP is a rare destructive chronic renal infection characterised by replacement of renal parenchyma with granulomatous inflammation and lipid-laden foamy macrophages (xanthoma cells). Associated with Proteus mirabilis (most common) or E. coli, obstructing staghorn calculi, and diabetes. The kidney is enlarged and non-functioning"]','A','XGP often mimics RCC on imaging (CT: enlarged kidney with multiple low-attenuation areas replacing parenchyma, central staghorn calculus, perinephric extension). Histology: sheets of lipid-laden macrophages (xanthoma cells) with scattered plasma cells, lymphocytes, and giant cells. Treatment: nephrectomy (medical treatment alone rarely successful due to extensive destruction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','flashcard','Describe the mechanism and histological findings of cisplatin nephrotoxicity','["Cisplatin (platinum-based chemotherapy) is filtered and concentrated in proximal tubular cells, where it forms DNA adducts and generates ROS → mitochondrial dysfunction, tubular cell apoptosis and necrosis. Predominant lesion: S3 segment (pars recta) of proximal tubule necrosis and collecting duct injury. Also causes distal tubular magnesium wasting → hypomagnesaemia"]','A','Cisplatin nephrotoxicity occurs in ~30-40% of patients. Hypomagnesaemia is a long-term complication from distal tubular damage. Prevention: aggressive pre- and post-hydration with saline, amifostine (ROS scavenger). Carboplatin is less nephrotoxic. Cumulative nephrotoxicity with repeated cycles. Monitor GFR and Mg2+ during treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','flashcard','Compare ADPKD and ARPKD: genetics, gene product, onset, and liver involvement','["ADPKD: PKD1 (polycystin-1, 16p13.3, ~85%) or PKD2 (polycystin-2, 4q21, ~15%); adult onset (3rd-5th decade); hepatic cysts (~83%, rarely cause liver failure). ARPKD: PKHD1 (fibrocystin/polyductin, 6p21.2); neonatal/childhood onset; congenital hepatic fibrosis (universal) → portal hypertension"]','A','Both polycystins and fibrocystin are localised to primary cilia of tubular epithelial cells — ciliary dysfunction (ciliopathy) is the unifying concept. ADPKD is common (1:1000); ARPKD is rare (1:20,000). Severity correlates with genotype: PKD1 worse than PKD2 (earlier ESRD by ~20 years). ARPKD kidneys show elongated collecting duct cysts; ADPKD shows spherical cysts from all nephron segments.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','flashcard','What are the extra-renal manifestations of ADPKD?','["1. Hepatic cysts (most common, ~83%). 2. Intracranial (Berry) aneurysms (~10-40%) — rupture causes subarachnoid haemorrhage. 3. Mitral valve prolapse (~25%). 4. Colonic diverticula. 5. Pancreatic cysts (~10%). 6. Seminal vesicle cysts. 7. Abdominal aortic/splenic artery aneurysms"]','A','The intracranial aneurysm risk is the most clinically important extra-renal manifestation — SAH risk is ~5-9% lifetime in ADPKD. Screening with MRA is recommended in patients with personal/family history of SAH or aneurysm. Hypertension (present in ~60% by age 30) accelerates cyst growth and is the most important modifiable risk factor for ESRD progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','flashcard','What is the ''two-hit hypothesis'' in ADPKD and why does it mean cysts are focal?','["Patients inherit one mutated PKD1 or PKD2 allele in all cells (germline mutation). Cysts develop only in tubular cells that acquire a second somatic mutation (''''second hit'''') inactivating the remaining normal allele, causing complete loss of polycystin function. As somatic mutations are random events, only a small fraction of cells acquire them — explaining why cysts are focal (only in those cells)"]','A','Despite being autosomal dominant (one allele mutated in all cells), cysts are focal because: (1) the remaining normal allele is sufficient for normal tubular function in most cells, and (2) only cells with somatic mutations in the second allele develop into cysts. This two-hit mechanism applies to other tumour suppressor genes (e.g., VHL, RB1). Both polycystins form a complex — loss of either causes loss of function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','flashcard','How does ARPKD cause neonatal death (Potter sequence)?','["Massive renal cyst enlargement in utero reduces or eliminates fetal urine production → oligohydramnios (reduced amniotic fluid) → Potter sequence: pulmonary hypoplasia (primary cause of neonatal death from respiratory failure), characteristic Potter facies (beaked nose, low-set ears, skin folds), and limb deformities from uterine compression"]','A','Amniotic fluid is largely comprised of fetal urine from the 2nd trimester onwards. Oligohydramnios therefore indicates severely reduced fetal urine output. In severe perinatal ARPKD, the kidneys are massively enlarged (may account for >60% of fetal weight) and the lungs are hypoplastic. Survivors require ventilatory support and eventually develop both renal and hepatic complications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','flashcard','What imaging finding is characteristic of ADPKD on renal ultrasound?','["Bilaterally massively enlarged kidneys replaced by innumerable cysts of varying sizes throughout the cortex and medulla. Diagnostic criteria (Pei, 2009): if PKD1 family history: ≥3 cysts total (age 15-39); ≥2 cysts per kidney (age 40-59). Hepatic cysts often visible"]','A','Ultrasound is the first-line imaging for ADPKD screening and diagnosis. CT and MRI provide more accurate measurement of total kidney volume (TKV), which is a prognostic biomarker and used to determine eligibility for tolvaptan. A rapid increase in TKV (>5%/year) predicts faster GFR decline. Genetic testing is reserved for atypical or uncertain cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','hard','flashcard','What is the mechanism of action of tolvaptan in ADPKD and what is its main adverse effect?','["Tolvaptan is a selective vasopressin V2 receptor (V2R) antagonist. V2R activation in collecting duct cells by ADH elevates cAMP → promotes cyst cell proliferation and fluid secretion into cysts. Tolvaptan blocks V2R → reduces cAMP → slows cyst growth and kidney enlargement → preserves GFR. Main adverse effect: hepatotoxicity (requires LFT monitoring; contraindicated in liver disease)"]','A','TEMPO 3:4 and REPRISE trials demonstrated tolvaptan slows GFR decline and TKV growth in ADPKD. It is approved for adults with rapidly progressive ADPKD (typically Mayo Class 1C-1E based on TKV/height ratio and age). Aquaretic side effects (polyuria, polydipsia, nocturia) are due to the V2R antagonism mechanism. Patients must maintain adequate fluid intake.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','flashcard','What is the natural history of ADPKD and when does ESRD typically occur?','["PKD1 mutations: median ESRD onset ~54-58 years. PKD2 mutations: median ESRD ~74-79 years. Earlier predictors of poor prognosis: male sex, PKD1 genotype, hypertension before age 35, first urological event before age 30, large total kidney volume (TKV), proteinuria"]','A','Most ADPKD patients remain in CKD stage 1-2 until their 4th-5th decade, when accelerating cyst growth outpaces renal compensation. Hypertension typically develops early (before GFR falls) from intrarenal RAAS activation as cysts compress vasculature. Renal pain, haematuria (cyst haemorrhage), and renal calculi are common complications before ESRD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','flashcard','What is medullary cystic kidney disease/nephronophthisis and how does it differ from ADPKD?','["Nephronophthisis (NPHP): autosomal recessive, presents in childhood/adolescence with tubulointerstitial nephritis, small kidneys with corticomedullary cysts, and ESRD by age 13-20 (juvenile form). Medullary cystic disease: autosomal dominant, adult onset, ESRD in 3rd-4th decade. Both: salt wasting, polyuria, polydipsia — unlike ADPKD which causes hypertension and enlarged kidneys"]','A','Nephronophthisis is caused by mutations in NPHP genes (encoding nephrocystins) — proteins localised to primary cilia. It is the most common genetic cause of ESRD in children and young adults. Extra-renal associations: retinitis pigmentosa (Senior-Loken syndrome), cerebellar ataxia, hepatic fibrosis. Small kidneys with corticomedullary cysts on US (different from ADPKD''''s massive enlargement).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','hard','flashcard','What are von Hippel-Lindau (VHL) disease renal manifestations and how do they differ from ADPKD?','["VHL disease (VHL gene mutation, 3p25.3): multiple bilateral clear cell RCC (not cysts primarily), renal cysts (precursor lesions to RCC), occur in 70% of VHL patients. Unlike ADPKD: VHL cysts are pre-malignant (clear cell RCC develops from cyst wall) and kidney size is variable. VHL also causes cerebellar/spinal haemangioblastomas, retinal haemangioblastomas, phaeochromocytoma"]','A','VHL patients require lifelong surveillance with annual renal imaging (CT/MRI) because ~70% develop RCC by age 60. VHL RCCs are often multifocal and bilateral. Surgical threshold: tumours >3 cm (below this, active surveillance; above this, partial or radical nephrecomy). Understanding VHL''''s role in HIF regulation led to development of VEGF/mTOR inhibitors for ccRCC treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','flashcard','What is tuberous sclerosis complex (TSC) and what renal lesions does it cause?','["TSC (TSC1/hamartin or TSC2/tuberin mutations, autosomal dominant): hamartomatous lesions in multiple organs. Renal lesions: angiomyolipomas (AMLs — benign tumours of blood vessels, smooth muscle, fat; risk of spontaneous haemorrhage if >4 cm), renal cysts (10%), rarely RCC. Skin: ash-leaf macules, shagreen patches, facial angiofibromas. Brain: cortical tubers, subependymal nodules, SEGA"]','A','TSC1 (9q34) and TSC2 (16p13.3) are tumour suppressors that negatively regulate mTOR pathway. Loss of function → mTOR overactivation → cell proliferation and growth (hamartomas). Everolimus (mTOR inhibitor) is approved for TSC-related AMLs, SEGAs, and pulmonary LAM. AMLs >4 cm: embolisation or resection to prevent haemorrhage (risk of Wunderlich syndrome).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','flashcard','What are the four main types of renal calculi and their approximate frequencies?','["1. Calcium stones (oxalate and phosphate) — ~70%. 2. Struvite (magnesium ammonium phosphate / triple phosphate) — ~15%. 3. Uric acid — ~5-10%. 4. Cystine — ~1-2%"]','A','Calcium stones are most common and radiopaque. Struvite stones are associated with urease-producing bacteria and form staghorn calculi. Uric acid stones are radiolucent and form in acidic urine. Cystine stones are poorly radiopaque, caused by cystinuria, and hexagonal crystals visible on urine microscopy. All stones need an organic matrix (Tamm-Horsfall protein scaffold).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','flashcard','Why do struvite stones form and which organisms are responsible?','["Struvite (magnesium ammonium phosphate) stones form when urease-producing bacteria split urea into ammonium and CO2, raising urinary pH to >7. Organisms: Proteus mirabilis (most common), Klebsiella pneumoniae, Pseudomonas aeruginosa, Enterococcus. E. coli does NOT produce urease. Struvite forms large ''staghorn calculi'' filling the renal pelvis and calyces"]','A','Staghorn calculi are stones that grow to fill the entire collecting system (pelvis + calyces = cast of the pelvis). They are almost always struvite. Complete surgical removal (PCNL) is the primary treatment — antibiotics alone cannot eradicate stones. If untreated, staghorn calculi cause progressive renal destruction, chronic pyelonephritis, and xanthogranulomatous pyelonephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','flashcard','Why are uric acid stones radiolucent and how can they be dissolved?','["Uric acid stones contain no calcium → not visible on plain X-ray (radiolucent). Visible on non-contrast CT scan (appear hyperdense relative to soft tissue). Form in acidic urine (pH <5.5) when uric acid is undissociated and poorly soluble. Dissolution: urinary alkalinisation with potassium citrate (target pH 6.5-7.0) dissolves existing stones and prevents new ones"]','A','Uric acid stone formers typically have very acidic urine (persistently low pH) — often associated with metabolic syndrome, gout, type 2 diabetes, myeloproliferative disorders, and high dietary purine intake. Defect in ammonium excretion in the proximal tubule leads to low urinary pH. Allopurinol reduces urate production. Alkalinisation with potassium citrate is highly effective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','flashcard','What are the main risk factors for calcium oxalate nephrolithiasis?','["Hypercalciuria (most common — absorptive, renal leak, or resortive), hyperoxaluria (dietary excess, Crohn disease, primary hyperoxaluria), hypocitraturia (citrate inhibits calcium crystallisation — reduced in distal RTA, low fruit/vegetable diet), low urine volume/dehydration, hyperuricosuria (urate crystal nidus for CaOx)"]','A','Citrate is the most important inhibitor of calcium crystallisation in urine. Citrate chelates calcium, reducing free calcium available for oxalate binding, and directly inhibits crystal aggregation. Potassium citrate supplementation is a first-line treatment for recurrent calcium oxalate stones in patients with hypocitraturia. Dietary advice: increase fluid intake to >2 L/day, restrict sodium and oxalate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','flashcard','What is the presentation of acute renal colic and which investigation is gold standard?','["Acute renal colic: sudden severe colicky flank pain radiating to the groin, nausea/vomiting, restlessness (cannot find comfortable position). Haematuria (micro or macro) in >90%. Investigation: non-contrast CT KUB (CTKUB) — gold standard, detects all stone types, >95% sensitivity/specificity"]','A','The pain of renal colic is caused by distension of the collecting system from obstruction. Stone passing at the ureterovesical junction causes dysuria and urinary urgency. Stones <5 mm pass spontaneously in ~90%; 5-10 mm ~50%; >10 mm rarely pass spontaneously. Medical expulsive therapy: alpha-blockers (tamsulosin) relax ureteral smooth muscle, facilitating stone passage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','hard','flashcard','What is primary hyperoxaluria type 1 and how does it cause kidney damage?','["Primary hyperoxaluria type 1 (PH1): autosomal recessive deficiency of alanine-glyoxylate aminotransferase (AGT) in liver peroxisomes. Glyoxylate cannot be converted to glycine → accumulates → oxidised to oxalate → massive urinary oxalate excretion → calcium oxalate deposits in kidneys (nephrocalcinosis) and urolithiasis from childhood. Progressive renal failure → oxalate deposited in bones, heart, eyes (systemic oxalosis)"]','A','PH1 (AGT on 2q36.2) and PH2 (glyoxylate reductase/GRHPR on 9q22.2) are the main types. Diagnosis: 24h urine oxalate (markedly elevated), liver biopsy for AGT activity, genetic testing. Treatment: pyridoxine (B6) reduces oxalate in B6-responsive PH1 (~30%), high fluid intake, urinary alkalinisation. Combined liver-kidney transplantation is curative for severe PH1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','flashcard','Cystinuria: inheritance, defect, stone appearance, and treatment','["Cystinuria: autosomal recessive defect in SLC3A1 (rBAT) or SLC7A9 (b0,+AT) — amino acid transporter for dibasic amino acids (Cystine, Ornithine, Arginine, Lysine — COAL) in proximal tubule and small intestine. Cystine is insoluble at normal urinary pH → forms pale yellow hexagonal crystals and stones. Treatment: high fluid intake (>3-4 L/day), urinary alkalinisation (pH >7.5), D-penicillamine or tiopronin (chelate cystine, forming more soluble disulphide compounds)"]','A','Cystine stones are partially radiopaque (faint opacity — ''ground glass''). Classic urine microscopy: hexagonal (benzene ring-shaped) crystals. Nitroprusside urine test: positive (purple colour) for excess cystine. Stones are hard and recurrent, often requiring PCNL or ESWL. Unlike most stones, ESWL is less effective for cystine stones (very hard). Dietary: reduce methionine (cystine precursor) and sodium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','flashcard','What metabolic abnormality in hyperparathyroidism leads to calcium nephrolithiasis?','["Primary hyperparathyroidism → excess PTH → (1) increased osteoclast bone resorption (releasing calcium and phosphate) → hypercalcaemia → hypercalciuria; (2) increased renal tubular 1-alpha-hydroxylase activity → increased calcitriol → increased intestinal calcium absorption → further hypercalciuria → calcium oxalate/phosphate stone formation"]','A','Hyperparathyroidism is a resortive cause of hypercalciuria. It accounts for ~5% of calcium nephrolithiasis. Diagnosis: elevated serum calcium + elevated PTH (failure of PTH suppression despite hypercalcaemia). Urine calcium >300 mg/day in men, >250 mg/day in women confirms hypercalciuria. Treatment of primary HPT: parathyroidectomy (curative and reduces stone recurrence).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','hard','flashcard','How does enteric hyperoxaluria cause calcium oxalate stones in Crohn disease?','["In Crohn disease (ileal disease or resection): malabsorbed fatty acids bind intestinal calcium (saponification) → reduced free Ca2+ in the bowel lumen → less calcium available to bind oxalate → increased free oxalate absorbed by the colon → hyperoxaluria → calcium oxalate urolithiasis. Dietary oxalate normally bound by calcium in the gut is now absorbed instead"]','A','Enteric hyperoxaluria is a complication of ileal disease or resection (Crohn, bowel bypass) and is the most common secondary cause of hyperoxaluria. The colon is more permeable to oxalate than the small intestine. Treatment: low-oxalate diet, calcium supplements WITH meals (to bind oxalate in the gut), cholestyramine (binds bile salts and oxalate), oral calcium oxalate crystal inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','flashcard','What is ESWL (extracorporeal shock wave lithotripsy) and which stone types respond best vs. worst?','["ESWL uses externally focused acoustic shock waves to fragment renal stones non-invasively. Best for: calcium oxalate monohydrate (medium hardness), calcium phosphate, struvite stones <2 cm. Worst response: calcium oxalate dihydrate (hardest), cystine stones (very hard, dense), staghorn calculi (need PCNL as primary treatment for stones >2 cm)"]','A','ESWL is first-line for stones 5 mm-2 cm in the renal pelvis or upper ureter. Contraindications: pregnancy, bleeding disorders, aortic/renal artery aneurysm, distal obstruction. Complications: haematoma (~25%), steinstrasse (stone fragments obstructing ureter), bacteraemia if treating struvite. PCNL (percutaneous nephrolithotomy) is preferred for staghorn calculi, hard stones >2 cm, or failed ESWL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','flashcard','What is the most common type of renal cell carcinoma and what gene is mutated?','["Clear cell RCC (ccRCC) — ~70-80% of all RCC. Associated with VHL (von Hippel-Lindau) tumour suppressor gene mutations (chromosome 3p25.3) in ~90% of sporadic cases and 100% of hereditary VHL syndrome cases. VHL loss → HIF stabilisation → VEGF/PDGF upregulation → angiogenesis"]','A','VHL normally targets HIF-1alpha and HIF-2alpha for proteasomal degradation via ubiquitin ligase complex. Loss of VHL → constitutive HIF expression → VEGF, EPO, PDGF, GLUT1 overexpression → highly vascularised tumours. This is the molecular rationale for using VEGF inhibitors (sunitinib, pazopanib) and mTOR inhibitors (everolimus) to treat ccRCC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','flashcard','What is the classic clinical triad of renal cell carcinoma?','["Flank pain + gross haematuria + palpable abdominal/flank mass. Now seen in only ~10% of patients (most RCC is discovered incidentally on abdominal imaging). Haematuria is the most common presenting symptom (~60% of cases)"]','A','Haematuria from RCC is typically painless (in contrast to stone-related haematuria which is painful). Painless haematuria in an adult always requires investigation to exclude urological malignancy. Other presentations: weight loss, fatigue, fever of unknown origin, symptoms from metastases (bone pain, cough from lung metastases). Paraneoplastic features in ~30%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','flashcard','List the paraneoplastic syndromes associated with renal cell carcinoma','["1. Polycythaemia (ectopic EPO — ~3%). 2. Hypercalcaemia (ectopic PTHrP — ~13%). 3. Hypertension (ectopic renin). 4. Cushing syndrome (ectopic ACTH). 5. Stauffer syndrome (non-metastatic hepatic dysfunction — abnormal LFTs, fever, reversible with nephrectomy). 6. Neuromyopathy. Total: paraneoplastic features in ~30% of cases"]','A','Paraneoplastic syndromes in RCC can precede, accompany, or follow the diagnosis. Hypercalcaemia (from ectopic PTHrP) is the most clinically important — can cause severe symptoms (confusion, polyuria, nausea, cardiac arrhythmias). Polycythaemia from EPO overproduction (ectopic EPO in cyst fluid or tumour cells) is an important secondary polycythaemia. Resection of tumour reverses most paraneoplastic syndromes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','flashcard','Papillary RCC vs. clear cell RCC: molecular differences, histology, and prognosis','["pRCC (~15% of RCC): MET proto-oncogene mutations (hereditary pRCC), trisomy 7+17 and loss of Y (sporadic). Histology: papillary architecture with foamy macrophages in papillary cores, psammoma bodies. Two types: Type 1 (less aggressive) and Type 2 (more aggressive). Prognosis: generally better than ccRCC at same stage. Not driven by VHL/HIF pathway"]','A','Hereditary papillary RCC syndrome (HPRC): germline MET activating mutations, bilateral/multifocal Type 1 pRCC. Sporadic pRCC also has MET mutations or trisomy 7 (gain of function via gene dosage). pRCC is less responsive to VEGF inhibitors than ccRCC (less dependent on VEGF pathway). MET inhibitors (cabozantinib, savolitinib) are being studied for pRCC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','flashcard','What are the common sites of metastasis from renal cell carcinoma?','["In order of frequency: Lung (~50-70% — ''cannonball'' metastases on CXR), Bone (~30-33% — lytic lesions, pathological fractures), Liver (~30%), Contralateral adrenal gland (~20%), Brain (~8%). RCC can also metastasise to unusual sites: thyroid, pancreas, skin, soft tissues (late-onset metastases 10-20 years after nephrectomy possible)"]','A','RCC metastases are classically lytic (osteolytic bone lesions) — can cause hypercalcaemia. Lung metastases may appear as multiple rounded ''cannonball'' lesions. The propensity for late recurrence (>10 years after nephrectomy) is characteristic of RCC. Solitary metastases (e.g., isolated lung or brain) can be resected for cure in some cases. Immunotherapy (nivolumab, ipilimumab) + VEGF inhibitors are first-line for metastatic ccRCC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','flashcard','Chromophobe RCC: associations, histology, and genetics','["Chromophobe RCC (~5% of RCC): associated with Birt-Hogg-Dube syndrome (FLCN mutation). Arises from cortical collecting duct intercalated cells. Histology: large pale cells with prominent cell membranes and perinuclear haloes (''fried egg appearance''); Hale''''s colloidal iron stain positive (mucopolysaccharide in cytoplasm). Genetics: multiple chromosomal losses (1, 2, 6, 10, 13, 17, 21). Best prognosis of all RCC subtypes (rare metastases)"]','A','Birt-Hogg-Dube syndrome (BHD): FLCN (folliculin) gene mutations (17p11.2), autosomal dominant. Features: chromophobe RCC + oncocytoma (mixed tumours), fibrofolliculomas (skin), pulmonary cysts and spontaneous pneumothorax. Fibrofolliculomas are pathognomonic of BHD. Unlike ccRCC, chromophobe RCC rarely responds to VEGF inhibitors — mTOR inhibitors or surgery are preferred.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','flashcard','What is the role of immunotherapy (checkpoint inhibitors) in metastatic RCC?','["Nivolumab (PD-1 inhibitor) + ipilimumab (CTLA-4 inhibitor) combination is approved first-line for intermediate/poor-risk metastatic ccRCC. Pembrolizumab + axitinib (VEGFR inhibitor) and nivolumab + cabozantinib are other approved first-line combinations. Mechanism: PD-1/PD-L1 blockade and CTLA-4 blockade release tumour-specific T-cell responses against RCC. Response rates: ~40% with durable responses"]','A','The CheckMate 214 trial established nivolumab + ipilimumab as superior to sunitinib in intermediate/poor-risk metastatic ccRCC with improved OS and CR rates. PD-L1 expression does not reliably predict response. Immune-related adverse events (irAEs) are the main toxicities: pneumonitis, colitis, hepatitis, hypophysitis. Combination VEGF + IO therapy (e.g., pembrolizumab + axitinib) provides broad efficacy across all risk groups.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','flashcard','What are the indications for partial nephrectomy vs. radical nephrectomy in localised RCC?','["Partial nephrectomy (nephron-sparing): preferred for T1a (≤4 cm), T1b (4-7 cm), solitary kidney, bilateral RCC, CKD, hereditary RCC syndromes (VHL, HPRC). Radical nephrectomy: T2+ (>7 cm), central tumours, local invasion (Gerota fascia, adrenal). Oncological outcomes equivalent for T1 disease; partial saves renal function"]','A','Nephron-sparing surgery preserves renal function and reduces long-term CKD risk. For T1 (<7 cm) tumours in suitable anatomy, partial nephrectomy is the standard of care. Laparoscopic and robotic approaches have equivalent oncological outcomes to open surgery for most T1-T2 tumours. Active surveillance is an option for elderly/comorbid patients with small (<3 cm) incidentally found tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','flashcard','What gross pathological features distinguish Wilms tumour (nephroblastoma) from adult RCC?','["Wilms tumour: children (peak age 3-4 years); grossly a large, well-circumscribed, soft, variegated tumour (white-grey with areas of necrosis/haemorrhage) within the kidney; histology: triphasic (blastemal, stromal, epithelial components). RCC: adults (peak 6th-7th decade); firm yellow/variegated tumour; no blastemal component. Both cause haematuria and flank mass but in very different age groups"]','A','Wilms tumour (nephroblastoma) is the most common renal tumour in children, associated with WT1 (11p13) or WT2 (11p15) mutations. Associated syndromes: WAGR (Wilms, Aniridia, GU anomalies, Retardation — WT1 deletion), Denys-Drash syndrome (WT1 mutation), Beckwith-Wiedemann syndrome (WT2/IGF2). Treatment: nephrectomy + chemotherapy; excellent prognosis (>90% survival).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','flashcard','Angiomyolipoma (AML) of the kidney: key features, risk factors, and management threshold','["AML = benign hamartoma composed of Abnormal blood vessels, smooth Muscle, and mature fat (Lipoma). Sporadic (90%): usually solitary, unilateral, in women >40. TSC-associated (10%): bilateral, multifocal, larger. Key risk: spontaneous haemorrhage (Wunderlich syndrome — retroperitoneal haemorrhage) if AML >4 cm due to abnormal thin-walled aneurysmal vessels. Management: AML <4 cm: annual surveillance. AML >4 cm or symptomatic: prophylactic embolisation or resection. TSC: everolimus (mTOR inhibitor) reduces AML size"]','A','AMLs appear as hyperechoic lesions on US (due to fat content) and show fat attenuation on CT (-10 to -20 HU). Biopsy may be needed for fat-poor AML. Rupture risk increases with size and presence of large aneurysms (>5 mm within AML). Prophylactic embolisation is preferred to preserve nephrons. Perivascular epithelioid cell tumours (PEComa) is the pathological classification — AML is a PEComa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','flashcard','What are the most important risk factors for urothelial (transitional cell) carcinoma of the bladder?','["1. Cigarette smoking (most important — ~50% of male and 35% of female bladder cancers). 2. Occupational aromatic amine exposure (2-naphthylamine, benzidine — rubber, dye, leather, paint industries). 3. Schistosoma haematobium infection (squamous cell type). 4. Cyclophosphamide/ifosfamide (acrolein metabolite). 5. Phenacetin abuse. 6. Pelvic irradiation"]','A','Aromatic amines are metabolised by hepatic N-acetyltransferases and N-hydroxylases. Slow acetylators (NAT2 polymorphism) are at higher risk as reactive hydroxylamine metabolites are excreted without detoxification. Bladder is uniquely vulnerable as urothelium is exposed to high concentrations of urinary carcinogens for prolonged contact time. Latency period for occupational exposure: 15-40 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','flashcard','What are the clinical features of bladder carcinoma in situ (CIS)?','["CIS (pTis): flat, non-papillary, high-grade urothelial carcinoma confined to the epithelium. Symptoms: irritative lower urinary tract symptoms (frequency, urgency, dysuria), haematuria. Cystoscopy: red, velvety, granular urothelium (may look normal). Urine cytology: positive (high-grade cells shed easily from CIS). Risk of progression to muscle-invasive disease: ~54% at 5 years untreated"]','A','CIS is a high-grade lesion despite being in situ. It is frequently multifocal and can involve the entire urothelial tract. Treatment: intravesical BCG immunotherapy (activates innate and adaptive immune response against CIS cells). BCG response rate: ~70-75% complete response. BCG failure: intravesical chemotherapy (gemcitabine), radical cystectomy for BCG-refractory CIS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','flashcard','Explain the two main molecular pathways of bladder cancer development','["1. Papillary pathway (FGFR3 mutations, RAS mutations): low-grade papillary tumours (pTa), good prognosis, high recurrence but low progression. 2. CIS/invasive pathway (TP53 mutations, RB1 loss, CDKN2A loss): flat high-grade CIS → muscle-invasive bladder cancer (MIBC), worse prognosis with high progression risk"]','A','These two pathways are largely distinct molecularly and clinically. Pathway 1 tumours are frequently FGFR3-mutated (>70% of pTa) and rarely progress to MIBC. Pathway 2 tumours lose TP53 and pRb function early, leading to genomic instability and invasive potential. Erdafitinib (FGFR inhibitor) is approved for FGFR-mutated metastatic urothelial carcinoma. Most MIBC shows pathway 2 features.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','flashcard','What is the TNM staging of bladder cancer and which stage marks a key therapeutic decision point?','["pTa: non-invasive papillary. pTis: CIS (flat). pT1: lamina propria invasion (not muscle). pT2: muscularis propria invasion (detrusor muscle) — KEY THRESHOLD (T2 = muscle-invasive). pT3: perivesical fat invasion. pT4: adjacent organs. pT2+ (muscle-invasive) requires radical cystectomy or chemoradiotherapy vs. surveillance for pTa/pT1"]','A','Muscle invasion (T2) is the critical threshold in bladder cancer management. Non-muscle-invasive bladder cancer (pTa, pTis, pT1): managed with TURBT ± intravesical therapy. Muscle-invasive bladder cancer (≥T2): radical cystectomy (gold standard) with neoadjuvant cisplatin-based chemotherapy, or bladder-sparing chemoradiotherapy (TURBT + concurrent cisplatin + radiotherapy). Lymph node dissection with cystectomy is standard.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','flashcard','Which infection is strongly associated with squamous cell carcinoma of the bladder?','["Schistosoma haematobium infection — endemic in sub-Saharan Africa, Egypt, and Middle East. Schistosome eggs deposited in bladder wall cause chronic granulomatous inflammation → squamous metaplasia → dysplasia → squamous cell carcinoma. Accounts for a significant proportion of bladder cancer in endemic regions"]','A','S. haematobium has a predilection for the venous plexus of the bladder. Egg deposition causes Th2 immune response, chronic inflammation, and epithelial metaplasia. In endemic regions, squamous cell carcinoma may equal or exceed urothelial carcinoma in frequency. Diagnosis: eggs visible in urine (or rectal biopsy). Treatment: praziquantel for schistosomiasis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','hard','flashcard','How does cyclophosphamide cause haemorrhagic cystitis and bladder cancer?','["Cyclophosphamide is hepatically activated to phosphoramide mustard (alkylating agent) and acrolein. Acrolein is excreted in urine and directly damages the urothelium: acute haemorrhagic cystitis (dysuria, haematuria, bladder fibrosis) and long-term risk of urothelial carcinoma. Prevention: MESNA (2-mercaptoethane sulphonate sodium) — binds and detoxifies acrolein in urine. Adequate hydration + frequent voiding also reduces exposure"]','A','Acrolein is an alpha,beta-unsaturated aldehyde that forms adducts with urothelial DNA. The risk of bladder cancer is dose-dependent (cumulative cyclophosphamide dose). MESNA reacts with the double bond of acrolein forming a non-toxic, non-absorbed MESNA-acrolein adduct in the urine. MESNA does not interfere with the chemotherapeutic action of cyclophosphamide. Ifosfamide also requires MESNA prophylaxis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','flashcard','What is the standard surveillance protocol for non-muscle-invasive bladder cancer after TURBT?','["Low-risk (single pTaG1 <3 cm): single post-TURBT intravesical chemotherapy (mitomycin C), then cystoscopy at 3 months and 12 months. High-risk (pT1G3, CIS, multiple/recurrent/large pTa): intravesical BCG (induction + maintenance) + cystoscopies at 3, 6, 12 months, then annually. Intermediate: adjuvant intravesical chemotherapy and cystoscopy every 3 months for 2 years"]','A','The high recurrence rate of bladder cancer (50-70%) necessitates lifelong surveillance. EAU guidelines stratify NMIBC into low, intermediate, and high risk based on tumour characteristics. BCG is the most effective intravesical agent for high-risk NMIBC (superior to chemotherapy). Cystoscopy + urine cytology at every surveillance visit. Progression to muscle-invasive: ~10-15% of high-risk NMIBC at 5 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','flashcard','What is malakoplakia of the bladder and what is its histological hallmark?','["Malakoplakia is a rare granulomatous inflammatory condition of the bladder (and other organs) associated with chronic E. coli infection, particularly in immunosuppressed patients. Gross: soft yellowish-brown plaques on bladder mucosa. Histological hallmark: von Hansemann macrophages (large granular histiocytes) containing Michaelis-Gutmann bodies — targetoid calcified inclusions from incompletely degraded bacteria"]','A','Michaelis-Gutmann bodies (PAS-positive, von Kossa-positive, calcium/iron staining) represent incompletely digested bacterial debris accumulating in macrophage lysosomes due to a defect in lysosomal killing. They appear as targetoid (bullseye) laminated calcifications. Treatment: antibiotics (ciprofloxacin, trimethoprim), bethanechol (increases cAMP to improve lysosomal function). Surgical excision for localised disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','hard','flashcard','What is the mechanism of intravesical BCG (Bacillus Calmette-Guerin) therapy in bladder cancer?','["BCG instilled into the bladder adheres to the urothelium via fibronectin attachment proteins. BCG is internalised by urothelial cells and macrophages → triggers both innate (NK cells, macrophages) and adaptive (CD4+ Th1, CD8+ cytotoxic T cells) immune responses → local cytokine release (IL-2, IFN-gamma, TNF-alpha) → anti-tumour immune effect against residual cancer cells. Mechanism not fully understood but requires intact immune response"]','A','BCG for bladder cancer is one of the oldest successful cancer immunotherapies. It was introduced by Morales in 1976. BCG failure (~30%): repeat BCG, gemcitabine/docetaxel intravesical, or radical cystectomy. Key side effects: cystitis (most common), BCGitis (systemic dissemination — fever, pneumonitis, hepatitis, sepsis) in immunosuppressed — treat with isoniazid/rifampicin + steroids. Absolute contraindication: immunocompromised, active UTI, traumatic catheterisation, haematuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','flashcard','What is the difference between papillary urothelial neoplasm of low malignant potential (PUNLMP) and low-grade papillary urothelial carcinoma?','["PUNLMP: papillary urothelial neoplasm with minimal cytological atypia — normal-appearing cells with slight architectural disorder. Very low risk of invasion or metastasis (<5%) but higher recurrence risk than normal. Low-grade papillary urothelial carcinoma (pTaG1/G2): mild to moderate nuclear atypia with more disorganised architecture. Higher recurrence rate (~50-70%) but low invasion risk (<5%)"]','A','The WHO 2004/2016 classification introduced PUNLMP as a distinct entity from urothelial papilloma (benign) and low-grade carcinoma. The distinction matters clinically: PUNLMP has excellent prognosis but still requires cystoscopic surveillance due to recurrence risk. Low-grade carcinoma has similar invasion risk but must be treated as cancer. Both are managed with TURBT and cystoscopic surveillance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','flashcard','Compare atherosclerotic renal artery stenosis vs. fibromuscular dysplasia: location, demographics, angiographic appearance','["Atherosclerosis: proximal 1/3 of renal artery and ostium; elderly men with cardiovascular risk factors; irregular concentric plaque narrowing on angiography. FMD: mid and distal renal artery; young-to-middle-aged women; classic ''string of beads'' appearance on angiography (alternating stenoses and microaneurysms from medial fibroplasia)"]','A','Atherosclerosis accounts for ~90% of renal artery stenosis. FMD accounts for ~10% but is the dominant cause in women <50. FMD responds well to percutaneous transluminal angioplasty (PTA) without stenting. Atherosclerotic RAS: stenting preferred (ostial lesions require stent support). Both cause renovascular hypertension via RAAS activation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','flashcard','How does renal artery stenosis cause hypertension?','["Reduced renal perfusion pressure → decreased stretch of juxtaglomerular apparatus (JGA) → increased renin secretion → angiotensin I → ACE → angiotensin II → vasoconstriction + aldosterone release → Na+/H2O retention → hypertension. This is RAAS-mediated secondary hypertension"]','A','Renovascular hypertension is classically resistant to conventional antihypertensive drugs. Clues: onset in young woman (FMD) or elderly patient with cardiovascular disease (atherosclerosis), abdominal bruit, hypokalaemia (from secondary hyperaldosteronism), flash pulmonary oedema, or worsening renal function after ACE inhibitor. Renal MRA or CT angiography confirms diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','flashcard','What is benign nephrosclerosis and what vascular lesion is pathognomonic?','["Benign nephrosclerosis: chronic renal injury from hypertension or ageing. Pathognomonic: hyaline arteriolosclerosis — homogeneous eosinophilic (PAS-positive) hyaline deposits replacing the smooth muscle cells in afferent arteriolar walls, causing luminal narrowing. Results in ischaemic glomerulosclerosis, tubular atrophy, and IFTA with slow progression"]','A','Hyaline arteriolosclerosis represents plasma protein insudation into the damaged arteriolar wall (from hypertensive endothelial injury). It is also seen in diabetes (arteriolar hyalinosis, particularly of the efferent arteriole in diabetes). Benign nephrosclerosis contributes to ~25% of ESRD (labelled hypertensive nephrosclerosis). Clinically: modest proteinuria, gradual GFR decline, difficult to diagnose without biopsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','flashcard','What are the histological findings in malignant hypertension affecting the kidney?','["1. Fibrinoid necrosis of afferent arterioles — eosinophilic fibrillar material (fibrin) replacing the arteriolar wall (acute, severe). 2. Hyperplastic arteriolosclerosis (''onion-skin lesion'') — concentric proliferation of smooth muscle cells and fibroblasts in interlobular artery intima, resembling onion-skin layers. Grossly: ''flea-bitten kidney'' — petechial cortical haemorrhages from arteriolar rupture"]','A','Malignant hypertension (hypertensive emergency with target organ damage) causes acute arteriolar injury with fibrinoid necrosis and a reactive cellular proliferation in arteriolar/arterial walls. The onion-skin lesion is the hallmark of malignant nephrosclerosis. Acute tubular injury and ischaemia lead to rapidly progressive renal failure. Treatment: controlled BP reduction (avoid rapid lowering which can precipitate ischaemia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','flashcard','What is renal vein thrombosis (RVT) and what nephrotic disease most commonly causes it?','["RVT: thrombosis of the renal vein causing renal venous outflow obstruction. Most strongly associated with membranous nephropathy (nephrotic syndrome) — ~35% of membranous nephropathy patients develop RVT due to urinary loss of antithrombin III, protein C, and protein S creating a hypercoagulable state. Presents with: flank pain, haematuria, worsening proteinuria, and acute renal failure"]','A','RVT can be acute (sudden flank pain, haematuria, renal failure) or chronic (gradual, often asymptomatic, discovered on contrast-enhanced CT/MRI showing intraluminal filling defect in renal vein). RCC tumour thrombus in renal vein is the other important cause. Treatment: anticoagulation (heparin → warfarin/NOAC); catheter-directed thrombolysis for acute bilateral RVT with severe renal failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','hard','flashcard','What is thrombotic microangiopathy (TMA) and how does haemolytic uraemic syndrome (HUS) differ from TTP?','["TMA = microthrombi in small vessels (arterioles, capillaries) causing MAHA (microangiopathic haemolytic anaemia), thrombocytopaenia, and organ ischaemia. HUS: triad of MAHA + thrombocytopaenia + AKI. Typical HUS: STEC (Shiga-toxin producing E. coli O157:H7) → endothelial injury in glomerular capillaries. TTP: ADAMTS13 deficiency → ultra-large vWF multimers → widespread platelet microthrombi. TTP: pentad (TMA + neurological symptoms + fever) — more systemic, less renal-predominant than HUS"]','A','Treatment differs critically: typical HUS (STEC) = supportive only (antibiotics are contraindicated — increase toxin release). Atypical HUS (complement-mediated) = eculizumab (anti-C5 monoclonal antibody). TTP = urgent plasma exchange (replaces deficient ADAMTS13 and removes inhibitor antibodies). Failure to distinguish leads to incorrect treatment. Renal biopsy in TMA: platelet-fibrin thrombi in glomerular capillaries, no IF deposits.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','flashcard','What are the renal manifestations of atheroembolic (cholesterol crystal) disease?','["Cholesterol crystals embolise from aortic atheromatous plaques to interlobular renal arteries → biconvex needle-shaped clefts (crystals dissolve in tissue processing) with giant cell reaction and intimal proliferation → ischaemia and gradually progressive renal failure. Skin: livedo reticularis, blue toe syndrome. Precipitants: aortic surgery, angiography/catheterisation, anticoagulation (dissolves protective fibrin cap)"]','A','Cholesterol crystal embolism (CCE) is often underdiagnosed. It can present acutely (post-procedure) or subacutely. Diagnosis: clinical features + skin biopsy showing cholesterol clefts in arterioles, or renal biopsy. No specific treatment — supportive. Avoid anticoagulation if possible (worsens outcome). Statins may stabilise plaques and reduce future embolisation. Prognosis: variable — some recover, many develop CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','flashcard','What is the ''string of beads'' angiographic appearance in FMD?','["In fibromuscular dysplasia (medial fibroplasia type — most common FMD), angiography of the renal artery shows alternating areas of stenosis and post-stenotic dilatation (microaneurysms) in the mid and distal artery, resembling a ''string of beads'' or pearl necklace. Bilateral in ~35% of cases"]','A','The ''string of beads'' pattern in FMD reflects alternating fibrous rings (stenosis) and areas of medial thinning with aneurysmal dilatation. It is a distinctive radiological finding. FMD is treated with percutaneous transluminal angioplasty (PTA) — excellent outcomes with cure or control of hypertension in ~80-90% of patients. Stenting is reserved for residual stenosis, dissection, or ostial lesions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','hard','flashcard','Describe the pathogenesis of sickle cell nephropathy','["Sickle cell disease: HbS polymerises in hypoxic/acidic/hyperosmolar environments → erythrocyte sickling → vaso-occlusion. The renal medulla is uniquely vulnerable (hypoxic, acidic, hyperosmolar) → medullary sickling → papillary necrosis (most common), haematuria, impaired urinary concentrating ability (hyposthenuria), renal tubular acidosis type 4. Long-term: focal segmental glomerulosclerosis (hyperfiltration) → proteinuria → CKD"]','A','Renal manifestations of sickle cell disease: (1) Haematuria — from medullary/papillary microinfarcts, even in sickle trait. (2) Hyposthenuria — inability to concentrate urine (loss of medullary concentration gradient from papillary damage) — one of the earliest manifestations. (3) Papillary necrosis — similar to analgesic nephropathy. (4) Glomerulopathy — membranoproliferative pattern or FSGS → nephrotic syndrome → CKD. ACE inhibitors are renoprotective in sickle nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','flashcard','What are the indications for renal revascularisation (angioplasty/stenting) in atherosclerotic renal artery stenosis?','["Indications: flash pulmonary oedema despite adequate medical therapy, resistant hypertension (failing 3+ antihypertensives), rapidly declining renal function, bilateral RAS or RAS in solitary kidney (ACE inhibitors contraindicated — risk of acute renal failure). Evidence: CORAL and ASTRAL trials showed no benefit of stenting over optimal medical therapy in most patients with stable renovascular hypertension"]','A','The CORAL and ASTRAL randomised trials demonstrated that renal artery stenting provided no benefit over optimal medical management (ACE inhibitor, statin, antiplatelet) in terms of BP control, renal function, or cardiovascular events in most patients with atherosclerotic RAS. Current evidence supports stenting primarily for the specific high-risk indications listed above. FMD responds better to angioplasty than atherosclerotic RAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','flashcard','What are the most common causative organisms of UTI, listed in order of frequency?','["1. E. coli (~80% community, ~50% hospital). 2. Staphylococcus saprophyticus (young sexually active women). 3. Klebsiella pneumoniae. 4. Proteus mirabilis (associated with struvite stones). 5. Enterococcus faecalis. 6. Pseudomonas aeruginosa (hospital/catheter-associated). 7. Candida albicans (immunocompromised/catheterised)"]','A','E. coli virulence factors for UTI: P fimbriae (pyelonephritis — binds P blood group antigen on urothelium), type 1 fimbriae (cystitis — bind mannose residues on urothelium), alpha-haemolysin (cytotoxin), aerobactin (iron acquisition), urovirulence plasmids. Proteus produces urease → struvite stones. S. saprophyticus ferments glucose → not oxidase positive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','flashcard','What are the risk factors for urinary tract infections in women vs. men?','["Women: short urethra (~4 cm, close proximity to perineum), sexual intercourse (mechanical introduction of bacteria), spermicides/diaphragm use (disrupt protective flora), postmenopausal oestrogen deficiency (reduces Lactobacillus colonisation, raises vaginal pH). Men: uncommon before age 50 (long urethra protects); after 50: BPH → urinary retention, catheterisation"]','A','Premenopausal women: UTI incidence 0.5/year. Recurrent UTI (>2/year) affects ~25% of women with prior UTI. Prophylaxis options: post-coital antibiotics, continuous low-dose prophylaxis, or cranberry products (type 1 fimbriae inhibition by proanthocyanidins). In men: UTI always warrants investigation for structural/functional abnormality. Asymptomatic bacteriuria in pregnancy requires treatment (risk of pyelonephritis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','flashcard','How does ascending infection reach the kidney and what factors promote pyelonephritis?','["Bacteria ascend from periurethra → bladder (cystitis) → ureter → renal pelvis → collecting ducts. Factors promoting ascent to kidney: vesicoureteral reflux (most important), urinary stasis/obstruction, catheter use, pregnancy (progesterone-induced ureteral dilatation), diabetes (impaired neutrophil function), immunosuppression, and high bacterial virulence (P fimbriae in E. coli)"]','A','Without VUR, infection usually remains in the bladder. VUR is the key factor allowing bacteria to ascend into the kidney. P fimbriae on uropathogenic E. coli bind to the urothelium of the ureter, resisting washout during micturition and facilitating ascent. Once in the renal pelvis, bacteria can enter collecting ducts, especially via compound papillae. Haematogenous pyelonephritis is uncommon (Staph. aureus, Candida).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','flashcard','What is the pathological basis and histological appearance of chronic pyelonephritis vs. acute pyelonephritis?','["Acute pyelonephritis: suppurative interstitial inflammation with neutrophil infiltrate, tubular necrosis, and abscesses. Gross: yellowish white cortical abscesses in linear streaks. Chronic pyelonephritis (reflux nephropathy): coarse cortical scars over dilated blunted calyces. Histo: interstitial fibrosis, tubular atrophy with ''thyroidisation'' (colloid-filled tubules resembling thyroid follicles), periglomerular fibrosis, lymphoplasmacytic infiltrate"]','A','''Thyroidisation'' of tubules in chronic pyelonephritis: atrophic tubules filled with eosinophilic proteinaceous casts (similar appearance to thyroid follicles). This is a non-specific feature of any severe chronic tubulointerstitial nephritis, not pathognomonic for pyelonephritis. Periglomerular fibrosis (fibrosis encircling the glomerulus) is also characteristic. Remaining glomeruli may show FSGS from hyperfiltration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','flashcard','What is emphysematous pyelonephritis and which patient population is most affected?','["Emphysematous pyelonephritis (EP): life-threatening necrotising infection with gas within the renal parenchyma from fermentation of glucose by gas-forming organisms (E. coli ~70%, Klebsiella). Affects predominantly diabetics (~90% of cases). CT: gas within the renal parenchyma. Treatment: emergency catheter drainage + IV antibiotics ± nephrectomy"]','A','Predisposing factors: diabetes mellitus (high tissue glucose for fermentation, impaired immune response), ureteric obstruction, immunosuppression. EP is a urological emergency with mortality of 20-40% without aggressive management. Class 1/2 EP (gas in collecting system or parenchyma only): nephrostomy + antibiotics usually sufficient. Class 3/4 EP (gas extension beyond kidney): nephrectomy often required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','flashcard','What is vesicoureteral reflux (VUR) and how is it classified?','["VUR: abnormal retrograde flow of urine from bladder into the ureter/renal pelvis, due to deficiency of the submucosal ureteral segment (prevents valvular mechanism). Grading (International Reflux Study Group): Grade I (ureter only), II (pelvis/calyces, no dilatation), III (mild dilatation), IV (moderate dilatation, blunted fornices), V (gross dilatation, tortuosity, intrarenal reflux)"]','A','Primary VUR: congenital short submucosal tunnel (intravesical ureteral segment normally 5:1 length:width ratio — reduced in VUR). Secondary VUR: bladder outlet obstruction (posterior urethral valves, BPH), neurogenic bladder. Diagnosis: voiding cystourethrogram (VCUG) or radionuclide cystogram (lower radiation). High-grade VUR (IV-V) in children: prophylactic antibiotics or surgical reimplantation to prevent renal scarring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','flashcard','What are the complications of pyelonephritis and which requires urgent drainage?','["Complications: 1. Perinephric abscess (fever not responding to antibiotics, tender flank mass) — requires percutaneous or surgical drainage. 2. Pyonephrosis (infected hydronephrosis — pus in obstructed collecting system) — requires urgent nephrostomy drainage. 3. Papillary necrosis (more common with DM, sickle cell). 4. Septicaemia/sepsis. 5. Emphysematous pyelonephritis (diabetics)"]','A','Pyonephrosis is a surgical emergency — the obstructed pus-filled kidney will not respond to antibiotics alone (inadequate drug penetration) and progresses to sepsis and permanent renal damage. CT diagnosis: dilated collecting system with gas or debris. Urgent percutaneous nephrostomy tube placement with antibiotics. Definitive treatment: remove obstruction (calculus, stricture) after infection controlled.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','flashcard','What is asymptomatic bacteriuria and when should it be treated?','["Asymptomatic bacteriuria (ASB): significant bacteriuria (≥10^5 CFU/mL of a single organism on two consecutive clean-catch specimens in women, one in men) without UTI symptoms. Treatment INDICATED: pregnancy (risk of pyelonephritis and preterm labour — treat with amoxicillin, nitrofurantoin, or cefuroxime), pre-urological procedures. NOT treated: non-pregnant women, elderly, catheterised patients, diabetics"]','A','Treating ASB in catheterised patients and elderly causes more harm than good (antibiotic resistance, adverse effects) without benefit. In pregnancy, untreated ASB leads to pyelonephritis in 25-30% (ascending from bacteriuria) and is associated with preterm birth. Screen all pregnant women at first antenatal visit (12-16 weeks) with MSU culture. Nitrofurantoin avoided in 3rd trimester (risk of neonatal haemolytic anaemia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','flashcard','What is the difference between cystitis and pyelonephritis clinically and on urinalysis?','["Cystitis (lower UTI): dysuria, urgency, frequency, suprapubic discomfort, no systemic features. Urinalysis: WBCs, bacteria, haematuria — NO casts. Pyelonephritis (upper UTI): fever (>38°C), rigors, flank/loin pain, CVA tenderness, nausea/vomiting ± lower UTI symptoms. Urinalysis: WBCs, bacteria, white cell casts (pathognomonic of upper UTI), haematuria, mild proteinuria"]','A','The presence of white cell casts is the key distinguishing feature — they can only form in the renal tubules and therefore indicate upper UTI (pyelonephritis). Blood cultures positive in ~20-30% of pyelonephritis. Fever with positive blood cultures = urosepsis. Treatment: cystitis — oral nitrofurantoin/trimethoprim 3-7 days. Uncomplicated pyelonephritis: oral ciprofloxacin 7 days or co-amoxiclav 14 days. Severe/complicated: IV gentamicin ± amoxicillin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','flashcard','What is the DMSA (dimercaptosuccinic acid) renal scan used for in the context of UTI/VUR?','["DMSA is a technetium-99m-labelled agent taken up by functioning renal proximal tubular cells. DMSA scan: (1) Detects renal cortical scarring from pyelonephritis/VUR (areas of reduced tracer uptake — ''cold spots''). (2) Measures differential renal function (relative contribution of each kidney). Performed 4-6 months after acute pyelonephritis to assess for permanent scarring. Preferred over IVP for scar detection"]','A','DMSA is the gold standard for detecting renal cortical scars (sensitivity ~96%). In children with UTI, DMSA 4-6 months post-infection determines whether scarring occurred — guides management of VUR. MAG3 (mercaptoacetyltriglycine) scan: measures renal perfusion and drainage (useful for obstruction assessment — diuresis renogram). DTPA (diethylenetriaminepentaacetic acid): GFR measurement + drainage assessment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');